import * as C from './core.js';
export function distribution(values,bins=8){const v=values.filter(x=>x!==''&&x!=null).map(Number).filter(Number.isFinite);if(!v.length)return {counts:Array(bins).fill(0),min:null,max:null,mean:null,n:0};const min=Math.min(...v),max=Math.max(...v),counts=Array(bins).fill(0);for(const x of v)counts[max===min?0:Math.min(bins-1,Math.floor((x-min)/(max-min)*bins))]++;return {counts,min,max,mean:C.mean(v),n:v.length};}
export function correlation(points){if(points.length<2)return null;const mx=C.mean(points.map(p=>p[0])),my=C.mean(points.map(p=>p[1]));let xy=0,xx=0,yy=0;for(const [x,y] of points){xy+=(x-mx)*(y-my);xx+=(x-mx)**2;yy+=(y-my)**2;}return xx&&yy?Math.max(-1,Math.min(1,xy/Math.sqrt(xx*yy))):null;}
let previewAxes=[0,1],filter=-1,filterModel=null;
export function applyClusterFilter(root,a){if(!a||filterModel!==a)return;root.querySelectorAll('#model-plot circle').forEach((dot,i)=>{const index=dot.dataset.point==null?i:+dot.dataset.point;if(index<a.X.length)dot.style.opacity=filter<0||a.model.labels[index]===filter?'1':'.12';});}
export function enhanceScreens(root,S,step,H){const {esc,fmt,plot,select,table,help,choose,upload}=H;const q=s=>root.querySelector(s);const el=(tag,cls,html='')=>{const n=document.createElement(tag);n.className=cls;n.innerHTML=html;return n;};const panel=(title,html)=>el('section','panel',`<h2>${title}</h2>${html}`);const unit=(j,d=S.data)=>d.units?.[j]||'units not supplied';
const hist=values=>{const d=distribution(values),peak=Math.max(1,...d.counts);return `<div class="distribution" role="img" aria-label="Eight equal-width bins: ${d.counts.join(', ')} examples. Missing values excluded.">${d.counts.map((n,i)=>`<span style="height:${n/peak*100}%" title="Bin ${i+1}: ${n}"></span>`).join('')}</div><p class="fine">Mean: ${fmt(d.mean)} · ${d.n} measured values</p>`;};
const metrics=a=>`<div class="metric-grid"><div><span>Inertia ${help('Inertia')}</span><strong>${fmt(a.model.inertia)}</strong></div><div><span>Silhouette ${help('Silhouette')}</span><strong>${fmt(a.model.silhouette)}</strong></div><div><span>Center updates</span><strong>${a.model.iterations}</strong></div><div><span>Termination</span><strong class="text-value">${a.model.converged?'Converged':'Iteration limit'}</strong></div></div><p class="fine">Calculated in the fitted feature space. Neither metric is accuracy or proof of useful categories.</p>`;
const profiles=a=>`<div class="profile-list">${a.model.centers.map((c,g)=>{const members=a.raw.filter((_,i)=>a.model.labels[i]===g);return `<article><h3>Cluster ${g+1} · ${members.length} examples</h3><p>${esc(a.names[g]||'Name after investigating')}</p>${a.prep.names.map((name,j)=>{const d=distribution(a.raw.map(r=>r[j])),v=members.length?C.mean(members.map(r=>r[j])):null,pct=v==null?0:d.max===d.min?50:(v-d.min)/(d.max-d.min)*100;return `<div class="profile-value"><span>${esc(name)}</span><b>${fmt(v)} ${esc(unit(a.prep.features[j],a.data))}</b><div class="range-track" aria-hidden="true"><i style="width:${pct}%"></i></div></div>`;}).join('')}</article>`;}).join('')}</div><p class="fine">Group means in original units. Bars locate each mean within that feature’s dataset range; bar lengths across different features are not comparable measurements.</p>`;
root.dataset.screen=String(S.stage);
if(S.stage===0){const load=q('#load-sample');const chips=el('div','quick-picks','<span class="fine">Quick pick</span>'+[['songs','Songs'],['air','Singapore air'],['penguins','Penguins'],['cars','Cars']].map(([key,label])=>`<button type="button" data-sample-pick="${key}">${label}</button>`).join(''));load.before(chips);chips.querySelectorAll('button').forEach(b=>b.onclick=()=>{q('#sample').value=b.dataset.samplePick;load.click();});const drop=q('#upload-csv');drop.innerHTML='<span>Upload CSV</span><small>Choose a file or drop it here · up to 2 MB</small>';drop.ondragover=e=>{e.preventDefault();drop.classList.add('dragover');};drop.ondragleave=()=>drop.classList.remove('dragover');drop.ondrop=async e=>{e.preventDefault();drop.classList.remove('dragover');try{if(e.dataTransfer.files.length!==1)throw Error('Drop one CSV file at a time.');await upload(e.dataTransfer.files[0]);}catch(err){H.notice(err.message);}};
const desc=C.describe(S.data),heads=q('.data-preview thead tr');[...heads.children].forEach((th,j)=>{if(desc[j].numeric)th.insertAdjacentHTML('beforeend',`<small>${esc(unit(j))}<br>${fmt(desc[j].min)} – ${fmt(desc[j].max)}</small>`);});q('.data-preview .sectionbar').after(el('p','dataset-quality',`${S.data.headers.length} columns · ${desc.reduce((n,d)=>n+d.missing,0)} missing cells · Display names remain metadata`));}
if(S.stage===1){const layout=q('.layout');layout.classList.add('feature-layout');q('fieldset').classList.add('feature-cards');q('fieldset').querySelectorAll('.check').forEach(label=>{const input=label.querySelector('input'),j=+input.dataset.feature,d=C.describe(S.data)[j];if(d.numeric)label.querySelector('span').insertAdjacentHTML('beforeend',hist(S.data.rows.map(r=>r[j])));});const right=el('div','screen-stack');layout.append(right);let prep;try{prep=C.prepare(S.data,S.features,S.scale,S.missing);}catch{}const preview=panel('Feature preview','<p class="hint">Inspect two measurements before training. Changing these axes changes only this preview.</p><div id="preview-controls" class="toolbar"></div><div id="feature-preview"></div><p id="feature-correlation" class="callout"></p>');right.append(preview,layout.querySelector('aside'));if(prep){previewAxes=previewAxes.map(x=>Math.min(x,prep.prep.names.length-1));const opts=prep.prep.names.map((n,j)=>[j,n]);q('#preview-controls').innerHTML=select('preview-x','Preview X feature',opts,previewAxes[0])+select('preview-y','Preview Y feature',opts,previewAxes[1]);const draw=()=>{const pts=prep.raw.map(r=>previewAxes.map(j=>r[j]));q('#feature-preview').innerHTML=plot(pts,[],[],previewAxes.map(j=>`${prep.prep.names[j]} (${unit(prep.prep.features[j])})`));q('#feature-correlation').textContent=`Pearson correlation: ${fmt(correlation(pts))}. ${prep.raw.length} prepared examples shown in original units. Correlation describes a linear relationship; it does not prove that features are useful or independent.`;};draw();['preview-x','preview-y'].forEach((id,i)=>q('#'+id).onchange=e=>{previewAxes[i]=+e.target.value;draw();});}else q('#feature-preview').textContent='Select at least two usable features to preview the prepared data.';}
if(S.stage===2){const layout=q('.layout'),workspace=layout.querySelector('section'),settings=layout.querySelector('aside');layout.classList.add('training-layout');const left=el('div','screen-stack'),right=el('div','screen-stack');layout.replaceChildren(left,right);left.append(panel('Clustering algorithm','<p><strong>K-means · K-means++ initialization</strong></p><p class="hint">Assign each example to its nearest center, then move each center to the mean of its group. All selected features contribute.</p>'),settings);settings.classList.remove('side');const playback=panel('Interactive playback','<p class="fine">Watch one initialization. Full training compares the configured number of initializations.</p>');const toolbar=workspace.querySelector('.toolbar');if(toolbar)playback.append(toolbar);for(const n of [...workspace.children])if(n.matches('p.hint'))playback.append(n);left.append(playback);right.append(workspace);const a=!S.stale&&S.active;let html;if(step){const inertia=step.labels?step.X.reduce((s,x,i)=>s+C.d2(x,step.centers[step.labels[i]]),0):null;html=`<div class="metric-grid"><div><span>Current inertia</span><strong>${fmt(inertia)}</strong></div><div><span>Center updates</span><strong>${step.iteration}</strong></div></div><p class="fine">${step.labels?'Calculated from the displayed assignments and centers.':'Assign examples to calculate inertia.'} Step mode is one learning run.</p>`;}else html=a?metrics(a):'<p class="hint">Train the model to calculate inertia, silhouette, and termination status.</p>';right.append(panel('Calculated training results',html));workspace.querySelector('.fine').insertAdjacentHTML('beforeend',' Standardized values below zero mean below the feature average, not negative physical measurements.');}
if(S.stage===3&&S.tab==='results'&&S.active&&!S.stale){const a=S.active;if(filterModel!==a){filterModel=a;filter=-1;}const layout=q('.layout'),main=layout.querySelector('section'),side=layout.querySelector('aside');layout.classList.add('explore-layout');const right=el('div','screen-stack');layout.append(right);right.append(panel('Feature signatures',profiles(a)),side);side.classList.remove('side');const clusters=main.querySelector('.clusters');if(clusters){const names=panel('Name and explain your clusters','');names.append(clusters);right.append(names);clusters.classList.add('profile-names');}const roster=panel('Cluster member records','<p class="hint">Choose a cluster to inspect its members. Select an example to see its original measurements and nearest neighbors.</p><div class="toolbar" id="cluster-filter"></div><div id="member-table"></div>');main.append(roster);q('#cluster-filter').innerHTML=select('member-cluster','Cluster filter',[[-1,`All clusters (${a.X.length})`],...a.model.centers.map((_,g)=>[g,`Cluster ${g+1} (${a.model.labels.filter(x=>x===g).length})`])],filter);const drawRoster=()=>{const ids=a.indices.map((_,i)=>i).filter(i=>filter<0||a.model.labels[i]===filter);q('#member-table').innerHTML=`<p class="fine">Showing ${ids.length} of ${a.X.length} examples. Filtering does not retrain or change the projection.</p><div class="tablewrap"><table><thead><tr><th>Example</th><th>Cluster</th>${a.prep.names.map(n=>`<th>${esc(n)}</th>`).join('')}</tr></thead><tbody>${ids.map(i=>`<tr><td><button type="button" data-member="${i}">${esc(a.display<0?`Row ${a.indices[i]+1}`:a.data.rows[a.indices[i]][a.display])}</button></td><td>${a.model.labels[i]+1}</td>${a.raw[i].map(v=>`<td>${fmt(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;q('#member-table').querySelectorAll('[data-member]').forEach(b=>b.onclick=()=>choose(+b.dataset.member));applyClusterFilter(root,a);};drawRoster();q('#member-cluster').onchange=e=>{filter=+e.target.value;drawRoster();};const two=q('#model-plot svg:not(.plot3d)');if(two){two.setAttribute('role','group');two.querySelectorAll('circle').forEach((dot,i)=>{dot.classList.add('inspect-point');dot.setAttribute('tabindex','0');dot.setAttribute('role','button');dot.setAttribute('aria-label',`${a.display<0?'Row '+(a.indices[i]+1):a.data.rows[a.indices[i]][a.display]}, Cluster ${a.model.labels[i]+1}`);dot.onclick=()=>choose(i);dot.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();choose(i);}};});}const copy=main.querySelector('.inspector>p');if(copy)copy.textContent='Each point is one example; features are its measurements. Select a point, choose a member record, or search below. Neighbor distances use all fitted features, not screen position.';}
if(S.stage===4){const layout=q('.layout');layout.classList.add('card-layout');const writing=layout.querySelector('section'),exports=layout.querySelector('aside'),a=S.active;const left=el('div','screen-stack'),right=el('div','screen-stack');layout.replaceChildren(left,right);exports.classList.remove('side');const actions=exports.querySelector('.toolbar');const top=el('div','panel export-actions','<div><h2>Review and export</h2><p class="fine">Download evidence for your presentation or separate reflection document.</p></div>');top.append(actions);layout.before(top);if(a){left.append(panel('A · Model overview',`<span class="badge">Software-generated facts${S.stale?' · Previous model — outdated':''}</span><dl class="facts"><dt>Algorithm</dt><dd>K-means · squared Euclidean assignment</dd><dt>Dataset</dt><dd>${esc(a.data.name)}</dd><dt>Examples fitted</dt><dd>${a.X.length}</dd><dt>Clusters</dt><dd>${a.model.centers.length}</dd><dt>Initialization</dt><dd>K-means++ · ${a.settings.restarts} initialization(s), seed ${a.settings.seed}</dd></dl>`),panel('B · Data and preprocessing',`<p>${esc(a.data.source)}</p><p>${esc(a.data.description||'')}</p>${table(['Feature','Unit','Fitted mean','Population SD'],a.prep.names.map((n,j)=>[n,unit(a.prep.features[j],a.data),fmt(a.prep.means[j]),fmt(a.prep.stds[j])]))}<p class="callout">${a.prep.scale?'Standardized using fitted means and population standard deviations.':'Original feature scales retained.'} Missing values: ${a.prep.missing==='mean'?'feature-mean imputation':'incomplete rows removed'}. ${a.removed} rows removed; ${a.filled} cells filled.</p>`),panel('C · Group profiles',profiles(a)));right.append(panel('D · Model diagnostics',metrics(a)),panel('E · Evidence and limitations',`<p>${S.runs.length} saved runs · ${a.examples.length} new-example investigations.</p><p>K-means assigns every example to a nearest center. A large distance is not low confidence; there is no confidence percentage.</p><p>Results depend on the selected features, scales, initialization and K. A t-SNE island does not prove a natural category.</p><h3>Student-recorded limitation</h3><p>${esc(a.notes.limitation||'Not recorded here. You may use a separate document.')}</p>`));}else left.append(panel('Calculated model facts','<p>Train a model to populate the overview, preprocessing, group profiles and diagnostics.</p>'));writing.querySelector('h2').childNodes[0].textContent='F · Student explanations ';left.append(writing);right.append(exports);}
}
